function executaQuery(query, constraints, dataSource) {
    try {
        var dataSource = dataSource;
        var ic = new javax.naming.InitialContext();
        var ds = ic.lookup(dataSource);

        var conn = ds.getConnection();
        var stmt = conn.prepareStatement(query);

        var counter = 1;
        for (var i = 0; i < constraints.length; i++) {
            var val = constraints[i];
            if (val.type == "int") {
                stmt.setInt(counter, val.value);
            }
            else if (val.type == "float") {
                stmt.setFloat(counter, val.value);
            }
            else if (val.type == "date") {
                stmt.setString(counter, val.value);
            }
            else if (val.type == "datetime") {
                stmt.setString(counter, val.value);
            } else {
                stmt.setString(counter, val.value);
            }
            counter++;
        }

        var rs = stmt.executeQuery();
        var columnCount = rs.getMetaData().getColumnCount();
        var retorno = [];

        while (rs.next()) {
            var linha = {};
            for (var j = 1; j < columnCount + 1; j++) {
                linha[rs.getMetaData().getColumnName(j)] = rs.getObject(rs.getMetaData().getColumnName(j)) + "";
            }
            retorno.push(linha);
        }

        return retorno;

    } catch (e) {
        log.error("ERRO==============> " + e.message);
        throw e;
    } finally {
        if (stmt != null) {
            stmt.close();
        }
        if (conn != null) {
            conn.close();
        }
    }
}
function executeInsert(query, constraints, dataSource) {
    var conn = null;
    var stmt = null;
    var insertedId = null;
    try {
        log.info("executandoQuery");
        log.info(query);
        log.dir(constraints);

        var ic = new javax.naming.InitialContext();
        var ds = ic.lookup(dataSource);

        conn = ds.getConnection();
        stmt = conn.prepareStatement(query, Packages.java.sql.Statement.RETURN_GENERATED_KEYS);

        var counter = 1;
        for (var i = 0; i < constraints.length; i++) {
            var val = constraints[i];
            if (val.type == "int") {
                stmt.setInt(counter, val.value);
            }
            else if (val.type == "float") {
                stmt.setFloat(counter, val.value);
            }
            else if (val.type == "date") {
                stmt.setString(counter, val.value);
            }
            else if (val.type == "datetime") {
                stmt.setString(counter, val.value);
            } else {
                stmt.setString(counter, val.value);
            }
            counter++;
        }

        // Use executeUpdate for INSERT and then try getGeneratedKeys
        var rowsAffected = stmt.executeUpdate();
        log.info("rowsAffected: " + rowsAffected);

        var rsKeys = stmt.getGeneratedKeys();
        if (rsKeys != null) {
            try {
                if (rsKeys.next()) {
                    insertedId = rsKeys.getInt(1);
                    log.info("generated id (getGeneratedKeys): " + insertedId);
                }
            } finally {
                try { rsKeys.close(); } catch (e) { }
            }
        }

        // Fallback for SQL Server when driver doesn't return generated keys
        if (insertedId == null) {
            try {
                var fallbackSql = "SELECT SCOPE_IDENTITY() AS ID";
                var fallbackStmt = conn.prepareStatement(fallbackSql);
                var rsScope = fallbackStmt.executeQuery();
                try {
                    if (rsScope.next()) {
                        insertedId = rsScope.getInt("ID");
                        log.info("generated id (SCOPE_IDENTITY): " + insertedId);
                    }
                } finally {
                    try { rsScope.close(); } catch (e) { }
                    try { fallbackStmt.close(); } catch (e) { }
                }
            } catch (e) {
                log.info("SCOPE_IDENTITY fallback failed: " + e);
            }
        }

    } catch (error) {
        var msg = "";
        if (error && error.javaException) {
            msg = error.javaException.getMessage();
        } else if (error && error.message) {
            if (error.message.Error) {
            } else {
                msg = error.message;
            }
        } else {
            msg = String(error);
        }

        log.error("ERRO==============> " + msg);
        log.error("Type of error: " + typeof error);
        log.error("Type of msg: " + typeof msg);

        throw "Erro ao executar Dataset: " + msg;

    } finally {
        if (stmt != null) {
            try { stmt.close(); } catch (e) { }
        }
        if (conn != null) {
            try { conn.close(); } catch (e) { }
        }
    }

    return insertedId;
}
function anexaDocumentoNoProcesso(documentId){
    var attachments = hAPI.listAttachments();
    var isAnexado = false;

    for (var i = 0; i < attachments.size(); i++) {
        if (documentId == attachments.get(i).getDocumentId()) {
            isAnexado = true;
        }
    }

    if (!isAnexado) {
        hAPI.attachDocument(documentId);
    }
}

function intermediateconditional58() {
    var numProcess = getValue("WKNumProces");
    var ds = DatasetFactory.getDataset("ds_form_aux_wesign", null, [
        DatasetFactory.createConstraint("numSolic",numProcess,numProcess,ConstraintType.MUST)
    ], null);

    log.info("verificaStatusAssinatura");
    log.dir(ds);


    for (var i = 0; i < ds.rowsCount; i++) {
        var status = ds.getValue(i, "statusAssinatura");
        log.info("status");
        log.info(status);
        hAPI.setCardValue("statusAssinatura", status);

        // Se o status da assinatura for igual a "Assinado"
        if (status == "Assinado") {

            // Pega a data de assinatura do form "ds_form_aux_wesign" do campo dataAssinatura (mesmo nome)
            var dataAssinado = ds.getValue(i, "dataAssinatura");

            // Se dataAssinatura (do form "ds_form_aux_wesign") não estiver como "null" então seta a data no campo dataAssinatura do form de Revitalização de Contrato.
            if (dataAssinado !== "null") {
                hAPI.setCardValue("dataAssinatura", dataAssinado);
                updateTcntAuxiliar_dataAssinatura(dataAssinado, hAPI.getCardValue("ID_TCNT_AUXILIAR"));
            }
            
            log.info("intermediate58 - antes do return true");
            return true;
        }

        if (status == "Pendente Assinatura") {
            return false;
        }
    }
}

function updateTcntAuxiliar_dataAssinatura(DATA_ASSINATURA, ID_TCNT_AUXILIAR){
    try {
        var query = "UPDATE TCNT_AUXILIAR SET DATA_ASSINATURA = ? WHERE ID = ?";
        executaUpdate(query, [
            {type:"date", value:DATA_ASSINATURA},
            {type:"int", value:ID_TCNT_AUXILIAR},
        ], "jdbc/CastilhoCustom");
    } catch (error) {
        throw error;
    }
}

function executaUpdate(query, constraints, dataSource) {
    try {
        var dataSource = dataSource;
        var ic = new javax.naming.InitialContext();
        var ds = ic.lookup(dataSource);

        var conn = ds.getConnection();
        var stmt = conn.prepareStatement(query);

        var counter = 1;
        for (var i = 0; i < constraints.length; i++) {
            var val = constraints[i];
            if (val.type == "int") {
                stmt.setInt(counter, val.value);
            }
            else if (val.type == "float") {
                stmt.setFloat(counter, val.value);
            }
            else if (val.type == "date") {
                stmt.setString(counter, val.value);
            }
            else if (val.type == "datetime") {
                stmt.setString(counter, val.value);
            } else {
                stmt.setString(counter, val.value);
            }
